esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint withdrawAmount) public payable {
        require(true);

        // Observe before state
        uint beforeBalance = address(c).balance;
        uint beforeDepositsCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        // perform the state-changing call as the owner (this contract is the owner since it deployed c)
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        uint afterBalance = address(c).balance;
        uint afterDepositsCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Single general assertion as required:
        // If reverted then no observable change; else depositsCount unchanged and balance decreased exactly by min(withdrawAmount, beforeBalance).
        assert(
            (reverted && afterBalance == beforeBalance && afterDepositsCount == beforeDepositsCount)
            || (
                !reverted
                && afterDepositsCount == beforeDepositsCount
                && beforeBalance >= afterBalance
                && (beforeBalance - afterBalance) == (withdrawAmount <= beforeBalance ? withdrawAmount : beforeBalance)
            )
        );
    }

    receive() external payable { }
}

