pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawAmount) internal {
        vm.assume(true);
        uint beforeBalance = address(c).balance;
        uint256 beforeDepositsCount;
        try c.depositsCount() returns (uint256 __r) { beforeDepositsCount = __r; } catch { return; }
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterDepositsCount;
        try c.depositsCount() returns (uint256 __r) { afterDepositsCount = __r; } catch { return; }
        assertTrue((reverted && afterBalance == beforeBalance && afterDepositsCount == beforeDepositsCount)
            || (
                !reverted
                && afterDepositsCount == beforeDepositsCount
                && beforeBalance >= afterBalance
                && (beforeBalance - afterBalance) == (withdrawAmount <= beforeBalance ? withdrawAmount : beforeBalance)
            ));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable { }
}
